{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '힘든 걸 말하는 건 이기적인 일이라는 배움'을 직접 언급하며, 내담자가 자기 욕구를 내세우는 것을 이기적으로 여기는 핵심 신념을 현재 대화에서 드러냄. 내담자가 '이기적이라는 소리를 들었으니까요'라고 확인한 부분과 정확히 일치."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "'내 필요나 힘듦을 앞세우는 것은 이기적이고 부끄러운 일이다'라는 태도가 상담사의 '이렇게 말해도 되는 건가' 반영과 직접 연결됨. 내담자가 힘들다고 말하려 할 때 막아서는 중간 신념."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/1"],
      "relevance": "'힘들어도 내색하지 않아야 하며'라는 규칙이 내담자가 주말 간병, 열두 시간 근무, 집안일·양육을 모두 감당하면서도 힘들다고 말하지 않는 패턴과 연결됨. 가족 모임에서 어머니가 당연하게 맡기는 상황도 이 규칙의 작동 사례."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/3"],
      "relevance": "'자신의 피로나 서운함을 묻는 말에는 괜찮아요로 답하며 자기 상태를 숨김'이라는 전략이 내담자가 배우자에게 '다 괜찮아'라고 얼버무리는 상황과 연결됨. 상담사가 '이 자리에선 어떻게 느껴지세요'라고 묻는 것은 이 회피 패턴을 풀어보려는 시도."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/1"],
      "relevance": "쌓인 피로가 아이에게 짜증으로 터진 뒤 죄책감을 느끼는 것이 내담자의 주호소(presenting problem)와 직접 연결됨. 가족 모임에서 당연하게 역할을 맡는 것이 피로를 축적시키는 맥락."
    }
  ]
}

